        u = q.popleft()
        if u == y:
            return dist[u]
        nxt = [u - 1, u + 1]
        if u % 11 == 0:
            nxt.append(u // 11)
        if u % 5 == 0:
            nxt.append(u // 5)
        for v in nxt:
