            v = a[i - 1][j] + b[i - 1][j]
            if i - limit - 1 >= 0:
                v -= b[i - limit - 1][j]
            a[i][j] = v % M
            w = a[i][j - 1] + b[i][j - 1]
            if j - limit - 1 >= 0:
                w -= a[i][j - limit - 1]
            b[i][j] = w % M
    return (a[zero][one] + b[zero][one]) % M

