    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = grid[0][0]
    dq = deque([(0, 0)])
    while dq:
        i, j = dq.popleft()
        d = dist[i][j]
        for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= x < m and 0 <= y < n:
                nd = d + grid[x][y]
                if nd < dist[x][y]:
                    dist[x][y] = nd
                    if grid[x][y]:
