def minTimeToReach(moveTime: List[List[int]]) -> int:
    n, m = len(moveTime), len(moveTime[0])
    INF = float("inf")
    dist = [[INF] * m for _ in range(n)]
    dist[0][0] = 0
    h = [(0, 0, 0)]
    while h:
        d, i, j = heapq.heappop(h)
        if d > dist[i][j]:
            continue
        if i == n - 1 and j == m - 1:
            return d
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
