def numberOfSequence(n: int, sick: List[int]) -> int:
    gaps = []
    inner_pow = 0
    if sick[0] > 0:
        gaps.append(sick[0])
    if sick[-1] < n - 1:
        gaps.append(n - 1 - sick[-1])
    for a, b in zip(sick, sick[1:]):
        g = b - a - 1
        if g > 0:
            gaps.append(g)
            inner_pow += g - 1
    total = sum(gaps)
    fact = [1] * (total + 1)
    for i in range(1, total + 1):
        fact[i] = fact[i - 1] * i % MOD
    res = fact[total]
    for g in gaps:
        res = res * pow(fact[g], MOD - 2, MOD) % MOD
    res = res * pow(2, inner_pow, MOD) % MOD
    return res

def maxPartitionsAfterOperations(s: str, k: int) -> int:
    n = len(s)
    # left[i]: greedy state of prefix s[0..i-1] -> (completed partitions, mask, distinct count)
    left = [(0, 0, 0)] * n
    num = mask = count = 0
    for i in range(n - 1):
        b = 1 << (ord(s[i]) - 97)
        if not (mask & b):
            count += 1
            if count <= k:
                mask |= b
            else:
                num += 1
                mask = b
                count = 1
        left[i + 1] = (num, mask, count)
    # right[i]: greedy state of suffix s[i+1..] (processed right to left)
    right = [(0, 0, 0)] * n
    num = mask = count = 0
    for i in range(n - 1, 0, -1):
        b = 1 << (ord(s[i]) - 97)
        if not (mask & b):
            count += 1
            if count <= k:
                mask |= b
            else:
                num += 1
                mask = b
                count = 1
        right[i - 1] = (num, mask, count)
    best = 0
    for i in range(n):
        ln, lm, lc = left[i]
        rn, rm, rc = right[i]
        seg = ln + rn + 2
        tot = bin(lm | rm).count("1")
        if lc == k and rc == k and tot < 26:
            seg += 1
        elif min(tot + 1, 26) <= k:
            seg -= 1
        if seg > best:
            best = seg
    return best

def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    m = len(s)
    S = int(s)
    base = 10 ** m

    def count_upto_digits(B: int) -> int:
        # count integers in [0, B] whose digits are all <= limit
        if B < 0:
            return 0
        ds = str(B)
        L = len(ds)
        res = 0
        for i, ch in enumerate(ds):
            d = ord(ch) - 48
            res += min(d, limit + 1) * (limit + 1) ** (L - i - 1)
            if d > limit:
                return res
        return res + 1

    def f(x: int) -> int:
        if x < S:
            return 0
        P, r = divmod(x, base)
        bound = P if r >= S else P - 1
        return count_upto_digits(bound)

    return f(finish) - f(start - 1)

