def maxValue(nums: List[int], k: int) -> int:
    n = len(nums)
    if k <= 0 or 2 * k > n:
        return 0
    B = max(1, max(nums).bit_length())
    V = 1 << B
    FULL = (1 << V) - 1
    # bitmasks[b] = set of values in [0, V) whose bit b is set
    bitmasks = []
    for b in range(B):
        m = 0
        for v in range(V):
            if (v >> b) & 1:
                m |= 1 << v
        bitmasks.append(m)

    def apply_or(S, num):
        # map every value v in set S to v | num
        for b in range(B):
            if (num >> b) & 1:
                M = bitmasks[b]
                S = (S & M) | (((S & (FULL ^ M)) << (1 << b)) & FULL)
        return S

    def sweep(arr):
        # res[i] = set (as mask) of ORs of exactly k elements chosen from arr[0..i]
        dp = [0] * (k + 1)
        dp[0] = 1  # value 0 with zero elements
        res = [0] * len(arr)
        for i, num in enumerate(arr):
            top = min(i + 1, k)
            for j in range(top, 0, -1):
                if dp[j - 1]:
                    dp[j] |= apply_or(dp[j - 1], num)
            res[i] = dp[k]
        return res

    pre = sweep(nums)
    suf = sweep(nums[::-1])[::-1]  # suf[i] = set from nums[i..]

    def to_list(mask):
        return [v for v in range(V) if (mask >> v) & 1]

    memo = {}
    best = 0
    for i in range(k - 1, n - k):
        pm = pre[i]
        sm = suf[i + 1]
        if not pm or not sm:
            continue
        key = (pm, sm)
        val = memo.get(key)
        if val is None:
            pl = to_list(pm)
            val = 0
            found = False
            for x in range(V - 1, -1, -1):
                for a in pl:
                    if (sm >> (a ^ x)) & 1:
                        val = x
                        found = True
                        break
                if found:
                    break
            memo[key] = val
        if val > best:
            best = val
    return best

def _z_function(s):
    n = len(s)
    z = [0] * n
    if n == 0:
        return z
    z[0] = n
    l = r = 0
    for i in range(1, n):
        if i < r:
            zi = z[i - l]
            if zi > r - i:
                zi = r - i
        else:
            zi = 0
        while i + zi < n and s[zi] == s[i + zi]:
            zi += 1
        z[i] = zi
        if i + zi > r:
            l = i
            r = i + zi
    return z


def minStartingIndex(s: str, pattern: str) -> int:
    n = len(s)
    m = len(pattern)
    z1 = _z_function(pattern + "#" + s)
    z2 = _z_function(pattern[::-1] + "#" + s[::-1])
    off = m + 1
    for i in range(n - m + 1):
        pref = z1[off + i]
        # suffix match ending at position i + m - 1 in s
        end = i + m - 1
        rev_pos = n - 1 - end
        suf = z2[off + rev_pos]
        if pref + suf >= m - 1:
            return i
    return -1

MOD = 10**9 + 7


def countWinningSequences(s: str) -> int:
    idx = {'F': 0, 'W': 1, 'E': 2}
    n = len(s)
    size = 2 * n + 1
    off = n

    def delta(b, a):
        if (b - a) % 3 == 1:
            return 1
        if (a - b) % 3 == 1:
            return -1
        return 0

    a0 = idx[s[0]]
    dp = [[0] * size for _ in range(3)]
    for b in range(3):
        dp[b][off + delta(b, a0)] = 1

    for i in range(1, n):
        a = idx[s[i]]
        total = [(x + y + z) % MOD for x, y, z in zip(dp[0], dp[1], dp[2])]
        new = []
        for b in range(3):
            src = [(t - d) % MOD for t, d in zip(total, dp[b])]
            d = delta(b, a)
            if d == 1:
                arr = [0] + src[:-1]
            elif d == -1:
                arr = src[1:] + [0]
            else:
                arr = src
            new.append(arr)
        dp = new

    res = 0
    for b in range(3):
        row = dp[b]
        res += sum(row[off + 1:])
    return res % MOD

