def maxSubarraySum(nums: List[int]) -> int:
    mx = max(nums)
    if mx <= 0:
        return mx
    INF = float("inf")
    f = {}
    pre = 0
    low = 0  # min plain prefix sum P[0..r-1]
    del_min = INF  # min over x of f[x]
    ans = -INF
    for v in nums:
        if v < 0:
            cur = f.get(v, INF)
            if low < cur:
                cur = low
            cur += v
            f[v] = cur
            if cur < del_min:
                del_min = cur
        pre += v
        m = low if low < del_min else del_min
        if pre - m > ans:
            ans = pre - m
        if pre < low:
            low = pre
    return int(ans)

def minLength(s: str, numOps: int) -> int:
    n = len(s)
    # L = 1: alternating pattern
    mis = sum(1 for i, ch in enumerate(s) if (ord(ch) - 48) != (i & 1))
    if min(mis, n - mis) <= numOps:
        return 1
    runs = []
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append(j - i)
        i = j
    lo, hi = 2, max(runs)
    while lo < hi:
        mid = (lo + hi) // 2
        need = 0
        for k in runs:
            need += k // (mid + 1)
        if need <= numOps:
            hi = mid
        else:
            lo = mid + 1
    return lo

