def _occurrences(text: str, pat: str):
    n = len(text)
    m = len(pat)
    if m == 0:
        return list(range(n + 1))
    if m > n:
        return []
    t = pat + "\x00" + text
    pi = [0] * len(t)
    res = []
    k = 0
    for i in range(1, len(t)):
        c = t[i]
        while k and t[k] != c:
            k = pi[k - 1]
        if t[k] == c:
            k += 1
        pi[i] = k
        if k == m:
            res.append(i - 2 * m)
    return res


def shortestMatchingSubstring(s: str, p: str) -> int:
    a, b, c = p.split("*")
    la, lb, lc = len(a), len(b), len(c)
    occ_a = _occurrences(s, a)
    occ_b = _occurrences(s, b)
    occ_c = _occurrences(s, c)
    if not occ_a or not occ_b or not occ_c:
        return -1
    best = -1
    for j in occ_b:
        # latest a-start i with i + la <= j
        idx = bisect_right(occ_a, j - la) - 1
        if idx < 0:
            continue
        i = occ_a[idx]
        kidx = bisect_left(occ_c, j + lb)
        if kidx == len(occ_c):
            continue
        k = occ_c[kidx]
        length = k + lc - i
        if best < 0 or length < best:
            best = length
    return best

def countSubstrings(s: str) -> int:
    n = len(s)
    ans = 0
    # dp[d][r]: number of substrings ending at previous position with value mod d == r
    mods = (3, 4, 6, 7, 8, 9)
    dp = {d: [0] * d for d in mods}
    trans = {}
    for d in mods:
        for c in range(10):
            trans[(d, c)] = [(r * 10 + c) % d for r in range(d)]
    psum3 = 0
    for i in range(n):
        c = ord(s[i]) - 48
        for d in mods:
            old = dp[d]
            t = trans[(d, c)]
            new = [0] * d
            for r in range(d):
                v = old[r]
                if v:
                    new[t[r]] += v
            new[c % d] += 1
            dp[d] = new
        if c == 1 or c == 2 or c == 5:
            ans += i + 1
        elif c != 0:
            ans += dp[c][0]
    return ans

